// The job API request itself failed (network error, API down, rate limited, etc).
// Log it clearly so it's visible in the execution log / eventual Failure Watchdog (SRS Workflow 10).
const error = $json.error || 'Unknown error';
console.error('[Signal Ingestion Poller] Failed to fetch jobs from source API:', error);

return [{
  json: {
    status: 'FAILED',
    workflow: 'signal-ingestion-poller',
    stage: 'fetch-jobs',
    error,
    failed_at: new Date().toISOString()
  }
}];

// Normalize the raw job API response into the hiring_signals shape used across
// the pipeline (company, role_title, hiring_type, source, dedupe_key, raw_payload).
// Written defensively: falls back gracefully if a field is missing or the API
// response shape shifts slightly, instead of crashing the whole poll.

const body = $input.first().json;
const rawJobs = Array.isArray(body.jobs) ? body.jobs : [];

// Cap how many postings we process per poll to keep each run lightweight.
// (Remotive doesn't offer a documented `limit` query param, so we slice client-side.)
const MAX_JOBS_PER_POLL = 5;
const jobs = rawJobs.slice(0, MAX_JOBS_PER_POLL);

if (jobs.length === 0) {
  // No new jobs this poll - not an error, just nothing to send.
  return [];
}

// Remotive job_type values -> our hiring_type enum (SRS section 9).
function mapHiringType(jobType) {
  const map = {
    internship: 'INTERN',
    full_time: 'FULL_TIME',
    part_time: 'CONTRACT',
    contract: 'CONTRACT',
    freelance: 'CONTRACT'
  };
  return map[jobType] || 'FULL_TIME';
}

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(16);
}

const items = [];

for (const job of jobs) {
  const companyName = job.company_name || 'Unknown Company';
  const roleTitle = job.title || 'Unspecified Role';
  const sourceUrl = job.url || `https://remotive.com/job/${job.id || simpleHash(roleTitle)}`;
  const hiringType = mapHiringType(job.job_type);

  // Domain isn't provided by this source - Enrichment Agent resolves it later,
  // so dedupe here keys on company name instead of domain.
  const dedupeKey = simpleHash(`${companyName}|${roleTitle}|${sourceUrl}`);

  items.push({
    json: {
      company: {
        name: companyName,
        domain: null
      },
      source: 'remotive_api',
      source_url: sourceUrl,
      role_title: roleTitle,
      hiring_type: hiringType,
      dedupe_key: dedupeKey,
      detected_at: new Date().toISOString(),
      raw_payload: {
        remotive_id: job.id || null,
        category: job.category || null,
        candidate_required_location: job.candidate_required_location || null,
        publication_date: job.publication_date || null,
        salary: job.salary || null
      }
    }
  });
}

return items;

// Log ingestion failures so they show up in the n8n execution log and can be
// picked up by Workflow 10 - Failure/Error Watchdog later.
const error = $json.error || 'Unknown error';
console.error('[Signal Ingestion Poller] Failed to send hiring signal to backend:', error);

return [{
  json: {
    status: 'FAILED',
    workflow: 'signal-ingestion-poller',
    stage: 'post-to-backend',
    error,
    failed_at: new Date().toISOString()
  }
}];

// Successful send - simple confirmation record for the execution log.
return [{
  json: {
    status: 'SUCCESS',
    workflow: 'signal-ingestion-poller',
    sent_at: new Date().toISOString(),
    response: $json
  }
}];
